"""Shorten overly long identifiers in the C generated by wasm2c.

wasm2c turns the demangled C++ function names in the wasm name section into
C identifiers, escaping characters such as ':' and '<'. Some template
instantiations produce identifiers that are several KB long, which MSVC
rejects with "fatal error C1064: compiler limit: token overflowed internal
buffer".

Every identifier longer than MAX_LENGTH characters is replaced with its first
KEEP_LENGTH characters followed by a hash of the whole identifier. The result
depends only on the identifier, so the same function gets the same name in
every file, and running the script again changes nothing.

Usage: shorten_names.py <generated files>...
"""

import hashlib
import re
import sys

MAX_LENGTH = 2047
KEEP_LENGTH = 1024

LONG_IDENTIFIER = re.compile(rb"\b[A-Za-z_][A-Za-z0-9_]{%d,}" % MAX_LENGTH)


def shorten(match: re.Match) -> bytes:
    name = match.group(0)
    digest = hashlib.sha256(name).hexdigest()[:16].encode()
    return name[:KEEP_LENGTH] + b"_h" + digest


def main(paths: list[str]) -> int:
    if not paths:
        print(__doc__.strip().splitlines()[-1], file=sys.stderr)
        return 1
    for path in paths:
        with open(path, "rb") as f:
            data = f.read()
        new_data, count = LONG_IDENTIFIER.subn(shorten, data)
        if count:
            with open(path, "wb") as f:
                f.write(new_data)
        print(f"{path}: shortened {count} identifiers")
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
